#include <ESP32-HUB75-MatrixPanelI2S-DMA.h>

// Panel configuration for 64x64 HUB75
const int PANEL_WIDTH = 64;
const int PANEL_HEIGHT = 64;

// Matrix object
MatrixPanel_I2S_DMA *dma_display = nullptr;

void setup() {
  Serial.begin(115200);

  // Configure panel parameters
  HUB75_I2S_CFG mxconfig(
    PANEL_WIDTH,   // Module width
    PANEL_HEIGHT,  // Module height
    1              // Chain length
  );

  // Optional: Custom pin overrides if needed (defaults match standard wiring)
  // mxconfig.gpio.r1 = 25;
  // mxconfig.gpio.g1 = 27;
  // ...

  // Initialize display with DMA support
  dma_display = new MatrixPanel_I2S_DMA(mxconfig);
  dma_display->begin();
  dma_display->setBrightness8(60); // Set brightness (0-255)
  dma_display->clearScreen();
}

void loop() {
  // Draw basic shapes and text
  dma_display->clearScreen();

  // Draw colorful border
  dma_display->drawRect(0, 0, 64, 64, dma_display->color4bit(15, 0, 0)); // Red border
  dma_display->drawRect(1, 1, 62, 62, dma_display->color4bit(0, 15, 0)); // Green inner border

  // Display scrolling text
  dma_display->setTextSize(1);
  dma_display->setTextColor(dma_display->color4bit(15, 15, 15)); // White text
  dma_display->setCursor(8, 28);
  dma_display->print("WAVESHARE");

  delay(2000);

  // Fill screen with flashing primary colors
  dma_display->fillRect(10, 10, 44, 44, dma_display->color4bit(0, 0, 15)); // Blue box
  delay(1000);
}
